def d2i(byte):
    """Digit value of one byte of a PIC 9 DISPLAY field, as GnuCOBOL sees it."""
    if byte & 0x0F == 0:
        return 0
    return byte - 0x30


def num_value(field):
    """Numeric value of an unsigned PIC 9(n) DISPLAY field."""
    value = 0
    for byte in field:
        value = value * 10 + d2i(byte)
    return value


def num_bytes(value, size):
    """Store a computed value back into an unsigned PIC 9(size) field."""
    return b"%0*d" % (size, abs(value) % (10 ** size))

